-- SQL Script for questions\nTRUNCATE TABLE questions;\nINSERT INTO questions (id, difficulty, type, category, subcategory, exam_type, text, image_url, code, options_json, correct_index, explanation) VALUES\n(1, 'easy', 'code', 'Fundamente', 'Citire si afisare date', 'Diverse', 'Ce afișează următorul cod pe ecran, dacă introduci de la tastatură numărul 5?', NULL, 'int x;\ncin >> x;\ncout << x * 2;', '["5","10","x * 2","Eroare"]'::jsonb, 1, 'Comanda cin citește valoarea 5 în variabila x. Apoi cout afișează 5 * 2, adică 10.'),\n(2, 'easy', 'choice', 'Fundamente', 'Citire si afisare date', 'Diverse', 'Cum afișezi corect textul "Salut" pe ecran în C++?', NULL, NULL, '["cin >> \"Salut\";","cout << \"Salut\";","print(\"Salut\");","scrie \"Salut\";"]'::jsonb, 1, 'Pentru a afișa un text pe ecran în C++, folosim comanda cout urmată de operatorul <<.'),\n(3, 'easy', 'choice', 'Fundamente', 'Citire si afisare date', 'Diverse', 'Dacă vrei să treci la rând nou pe ecran, ce poți folosi împreună cu cout?', NULL, NULL, '["endl","space","next","enter"]'::jsonb, 0, 'Cuvântul endl vine de la "end line" (sfârșit de rând) și mută textul următor pe un rând nou.'),\n(4, 'easy', 'choice', 'Fundamente', 'Operatori si expresii', 'Diverse', 'Ce rezultat are expresia matematică 10 % 3 în C++?', NULL, NULL, '["3","1","0","3.33"]'::jsonb, 1, 'Operatorul % calculează restul împărțirii. 10 împărțit la 3 dă 3, rest 1. Deci rezultatul este 1.'),\n(5, 'easy', 'choice', 'Fundamente', 'Operatori si expresii', 'Diverse', 'Care este rezultatul calculului 5 / 2 în C++?', NULL, NULL, '["2.5","3","2","0"]'::jsonb, 2, 'În C++, când împarți două numere întregi (fără virgulă), rezultatul este tot întreg. Partea zecimală (0.5) este ștearsă.'),\n(6, 'medium', 'choice', 'Fundamente', 'Operatori si expresii', 'Diverse', 'Ce valoare va avea variabila x după codul următor?', NULL, 'int x = 5;\nx++;', '["4","5","6","10"]'::jsonb, 2, 'Operatorul ++ crește valoarea variabilei cu 1. Deci a devine 5 + 1 = 6.'),\n(7, 'medium', 'choice', 'Fundamente', 'Operatori si expresii', 'Diverse', 'Ce valoare are expresia următoare?', NULL, '10 - 5 / 2 * 3', '["6","2.5","4","7.5"]'::jsonb, 2, 'Înmulțirea și împărțirea se fac primele, de la stânga la dreapta. 5 / 2 = 2. Apoi 2 * 3 = 6. La final: 10 - 6 = 4.'),\n(8, 'medium', 'choice', 'Fundamente', 'Operatori si expresii', 'Diverse', 'Ce rezultat dă această condiție logică?', NULL, '!(2 > 3 || 3 > 4)', '["0","1","2","Eroare"]'::jsonb, 1, 'Ambele condiții din paranteză sunt false (0). Semnul ! înseamnă negație (NOT). Opusul lui 0 (Fals) este 1 (Adevărat).'),\n(9, 'medium', 'choice', 'Fundamente', 'Structuri de control', 'Diverse', 'Câte numere va afișa următorul cod ?', NULL, 'for (int i = 1; i <= 5; i++) {\n    cout << i;\n}', '["4","5","6","Niciunul"]'::jsonb, 1, 'Condiția este i <= 5, pornind de la 1. Deci va afișa: 1, 2, 3, 4, 5. În total 5 repetări.'),\n(10, 'medium', 'code', 'Fundamente', 'Structuri de control', 'Diverse', 'Completează condiția pentru a verifica dacă un număr x este strict pozitiv.', NULL, 'if (________) {\n    cout << "Pozitiv";\n}', '["x = 0","x > 0","x < 0","x == 0"]'::jsonb, 1, 'Un număr este strict pozitiv dacă este strict mai mare decât zero (x > 0).'),\n(11, 'medium', 'choice', 'Fundamente', 'Structuri de control', 'Diverse', 'Care va fi valoarea finală a variabilei p?', NULL, 'int p = 1;\nint i = 1;\nwhile (i <= 3) {\n    p = p * i;\n    i++;\n}', '["3","4","6","12"]'::jsonb, 2, 'Codul înmulțește numerele de la 1 la 3: 1 * 1 = 1; 1 * 2 = 2; 2 * 3 = 6. Rezultatul final (p) este 6.'),\n(12, 'medium', 'choice', 'Fundamente', 'Structuri de control', 'Diverse', 'Ce afișează această secvență?', NULL, 'for (int i = 1; i <= 5; i++) {\n    if (i % 2 == 0) {\n        cout << i << " ";\n    }\n}', '["1 2 3 4 5","1 3 5","2 4","0"]'::jsonb, 2, 'Condiția i % 2 == 0 verifică dacă numărul este par. Din numerele 1,2,3,4,5, doar 2 și 4 sunt pare.'),\n(13, 'easy', 'choice', 'Fundamente', 'Complexitati', 'Diverse', 'Dacă un algoritm execută exact 10 pași indiferent de cât de mari sunt datele de intrare, ce complexitate (timp) are?', NULL, NULL, '["O(n)","O(1)","O(n^2)","O(log n)"]'::jsonb, 1, 'O(1) înseamnă "timp constant". Adică algoritmul face mereu același număr de pași, indiferent de cât de mare e numărul introdus de noi (n).'),\n(14, 'medium', 'choice', 'Fundamente', 'Complexitati', 'Diverse', 'Ce complexitate de timp are acest cod?', NULL, 'for (int i = 0; i < n; i++) {\n    for (int j = 0; j < n; j++) {\n        cout << i + j;\n    }\n}', '["O(1)","O(n)","O(n^2)","O(log n)"]'::jsonb, 2, 'Primul for se repetă de n ori. Pentru fiecare pas, al doilea for se repetă tot de n ori. Deci facem n * n pași, adică O(n^2).'),\n(15, 'hard', 'choice', 'Fundamente', 'Complexitati', 'Diverse', 'Un agoritm eficient de căutare a unei valori într-un vector sortat de elemente este cel de căutare binară (Binary Search). Ce complexitate are acest algoritm?', NULL, 'int binarySearch(int arr[], int size, int target) {
    int left = 0;
    int right = size - 1;
    while (left <= right) {
        int mid = left + (right - left) / 2;
        if (arr[mid] == target)
            return mid;
        if (arr[mid] < target)
            left = mid + 1;
        else
            right = mid - 1;
    }
    return -1;
}', '["O(1)","O(n)","O(n^2)","O(log n)"]'::jsonb, 3, 'Orice algoritm care împarte repetat problema la 2 (cum face căutarea binară) are o complexitate de O(log n), fiind foarte eficient.'),\n(16, 'medium', 'choice', 'Organizarea Datelor', 'Vectori', 'Diverse', 'Pe ce poziție (index) se află primul element din vectorul v?', NULL, 'int v[5] = {10, 20, 30, 40, 50};', '["1","0","v","Nu se poate determina"]'::jsonb, 1, 'În limbajul C++, indexarea vectorilor (numărătoarea elementelor) începe mereu de la poziția 0.'),\n(17, 'medium', 'choice', 'Organizarea Datelor', 'Vectori', 'Diverse', 'Ce valoare va avea suma calculată în acest cod?', NULL, 'int v[4] = {1, 2, 3, 4};\nint s = 0;\nfor (int i = 0; i < 3; i++) {\n    s = s + v[i];\n}', '["4","0","10","6"]'::jsonb, 3, 'Codul parcurge și adună elementele de la indexul 0 până la indexul 2 în variabila s: 1 + 2 + 3 = 6. '),\n(18, 'medium', 'choice', 'Organizarea Datelor', 'Vectori', 'Diverse', 'Dacă avem un vector v, ce algoritm descrie următoarea secvență de cod?', NULL, 'bool sortat = false;\nwhile (!sortat) {\n    sortat = true;\n    for (int i = 0; i < n - 1; i++) {\n        if (v[i] > v[i+1]) {\n            int temp=v[i]; v[i]=v[i+1]; v[i+1]=temp;\n            sortat = false;\n        }\n    }\n}', '["Cautare Liniara","Bubble Sort","Cautare Binara","Selection Sort"]'::jsonb, 1, 'Acesta este algoritmul de sortare Bubble Sort (metoda bulelor). Verifică vecinii și îi inversează până când tot vectorul este ordonat.'),\n(19, 'hard', 'choice', 'Organizarea Datelor', 'Matrice', 'Diverse', 'Câte elemente are în total această matrice bidimensională?', NULL, 'int a[3][3];', '["3","6","9","1"]'::jsonb, 2, 'Numărul total de elemente dintr-o matrice se află înmulțind numărul de linii cu numărul de coloane: 3 * 3 = 9.'),\n(20, 'hard', 'code', 'Organizarea Datelor', 'Matrice', 'Diverse', 'Cum verifici dacă un element de la linia i și coloana j face parte din diagonala principală a unei matrice pătratice?', NULL, 'if (________) {\n    cout << "Este pe diagonala principala";\n}', '["i == j","i + j == n - 1","i < j","i > j"]'::jsonb, 0, 'Pe diagonala principală, indicele liniei este mereu egal cu indicele coloanei (ex: 0,0 sau 1,1 sau 2,2). Deci condiția este i == j.'),\n(21, 'hard', 'choice', 'Organizarea Datelor', 'Matrice', 'Diverse', 'Unde se află elementele dintr-o matrice pentru care i < j (indexul liniei este mai mic decât indexul coloanei)?', NULL, NULL, '["Sub diagonala principala","Deasupra diagonalei principale","Pe diagonala secundara","Pe prima linie"]'::jsonb, 1, 'Elementele cu i==j se afla pe diagonala principală, cele cu i<j se afla deasupra diagonalei principale, iar cele cu i>j se afla sub diagonala principală.'),\n(22, 'easy', 'choice', 'Organizarea Datelor', 'Siruri de caractere', 'Diverse', 'Ce caracter special se află, invizibil, la finalul oricărui cuvânt (șir de caractere) în C++?', NULL, NULL, '["\\n","\\0","\\t","."]'::jsonb, 1, 'În C++, orice șir de caractere (text) se termină cu caracterul special null (\0) pentru ca programul să știe unde se oprește textul.'),\n(23, 'medium', 'choice', 'Organizarea Datelor', 'Siruri de caractere', 'Diverse', 'Câte caractere (litere) va returna funcția strlen pentru cuvântul "examen"?', NULL, 'cout << strlen("examen");', '["5","6","7","0"]'::jsonb, 1, 'Funcția strlen numără exact literele pe care le vedem. "examen" are 6 litere.'),\n(24, 'medium', 'choice', 'Organizarea Datelor', 'Siruri de caractere', 'Diverse', 'Ce se va afișa pe ecran?', NULL, 'char s[10] = "examen";\ns[2] = ''\0'';\ncout << s;', '["examen","ex","exa","eroare"]'::jsonb, 1, 'Am pus \0 pe poziția 2 (a treia literă, care era "a"). Afișarea se oprește la primul \0, deci se vor afișa doar literele de pe pozițiile 0 și 1: "ex".'),\n(25, 'easy', 'choice', 'Organizarea Datelor', 'Siruri de caractere', 'Diverse', 'Ce face funcția predefinită strcpy(destinatie, sursa)?', NULL, NULL, '["Aduna doua texte","Copiaza textul din sursa in destinatie","Numara literele din sursa","Verifica daca sunt la fel"]'::jsonb, 1, 'Numele strcpy vine de la "string copy" (copiere de șir). Ea șterge ce era în variabila destinație și scrie textul din sursă peste.'),\n(26, 'medium', 'choice', 'Organizarea Datelor', 'Structuri de date (struct)', 'Diverse', 'Cum accesăm nota unui elev (o variabilă) grupată într-un "struct Elev"?', NULL, 'struct Elev { int nota; };\nElev e;\n// Cum ii dam nota 10?', '["e(nota) = 10;","Elev[nota] = 10;","e.nota = 10;","nota = 10;"]'::jsonb, 2, 'Pentru a accesa componentele unui struct, folosim operatorul punct (.). Variabila e urmată de punct și numele componentei: e.nota.'),\n(27, 'medium', 'choice', 'Organizarea Datelor', 'Structuri de date (struct)', 'Diverse', 'Pentru declaraţia de mai jos precizaţi care din instrucţiunile de atribuire este greşită:', NULL, 'struct elev{
 char nume[20];
 int nota1;
 int nota2;
} e1,e2;', '["e1=e2+1;","e1.nume[2]=’x’;","e1=e2;","e1.nota1=e2.nota2+1;"]'::jsonb, 0, 'Nu poți aduna un număr întreg direct la o variabilă de tip struct (e1 = e2 + 1 este o operație invalidă în C++).'),\n(28, 'medium', 'choice', 'Organizarea Datelor', 'Structuri de date (struct)', 'Diverse', 'Dacă avem un vector de structuri, cum afișăm numele celui de-al doilea elev?', NULL, 'struct Elev { char nume[20]; };\nElev clasa[30];', '["clasa[1].nume","clasa[2].nume","clasa.nume[1]","nume.clasa[2]"]'::jsonb, 0, 'Primul elev e la pozitia 0, al doilea e la pozitia 1. Deci clasa[1] e elevul, iar .nume accesează câmpul lui.'),\n(29, 'medium', 'code', 'Subprograme', 'Transmitere prin valoare', 'Diverse', 'Completează ce cuvânt cheie folosim pentru o funcție care NU trebuie să returneze niciun rezultat înapoi (doar afișează ceva)?', NULL, '________ afisareSalut() {\n    cout << "Salut!";\n}', '["int","void","return","bool"]'::jsonb, 1, 'Cuvântul void (care înseamnă "gol" în engleză) se pune înaintea unei funcții care doar execută acțiuni și nu trimite înapoi (return) nicio valoare.'),\n(30, 'medium', 'choice', 'Subprograme', 'Transmitere prin valoare', 'Diverse', 'Care este rezultatul acestei funcții dacă o apelăm cu numar(4)?', NULL, 'int numar(int x) {\n    return x + 1;\n}', '["4","5","x","0"]'::jsonb, 1, 'Funcția primește 4, adună 1 și returnează 5.'),\n(31, 'medium', 'choice', 'Subprograme', 'Transmitere prin valoare', 'Diverse', 'Ce se va afișa pe ecran?', NULL, 'void modifica(int x) {\n    x = 10;\n}\n\nint main() {\n    int a = 5;\n    modifica(a);\n    cout << a;\n}', '["10","5","0","Eroare"]'::jsonb, 1, 'Când o variabilă e trimisă prin valoare (normal, fără caracterul &), funcția primește doar o clonă (o copie). Deci modificarea lui x în 10 nu îl afectează pe a, care rămâne tot 5 în main.'),\n(32, 'easy', 'choice', 'Subprograme', 'Transmitere prin valoare', 'Diverse', 'Variabilele create în interiorul unei funcții se numesc variabile locale. Ce se întâmplă cu ele la terminarea funcției?', NULL, NULL, '["Se sterg din memorie","Raman salvate in calculator pe veci","Pot fi folosite in main","Se salveaza in fisiere"]'::jsonb, 0, 'Variabilele locale trăiesc doar cât timp funcția lucrează. După ce funcția se termină (la acolada de închidere), ele sunt distruse automat.'),\n(33, 'medium', 'choice', 'Subprograme', 'Transmitere prin referinta', 'Diverse', 'Ce simbol folosim în C++ în fața parametrului unei funcții pentru ca modificările să afecteze variabila originală (prin referință)?', NULL, 'void schimba(int ___x) {
	x=x*2;
}', '["*","#","&","%"]'::jsonb, 2, 'Simbolul & (ampersand) leagă variabila din funcție direct de variabila originală. Astfel, funcția modifică direct originalul.'),\n(34, 'medium', 'choice', 'Subprograme', 'Transmitere prin referinta', 'Diverse', 'Ce se va afișa pe ecran?', NULL, 'void swap(int &x, int &y) {\n    int temp = x;\n    x = y;\n    y = temp;\n}\nint main() {\n    int a = 1, b = 2;\n    swap(a, b);\n    cout << a << " " << b;\n}', '["1 2","2 1","0 0","1 1"]'::jsonb, 1, 'Deoarece am folosit referința (&), funcția swap (interschimbare) a inversat direct valorile variabilelor originale a și b. Deci ele devin 2 și 1 (nu 1 și 2).'),\n(35, 'hard', 'choice', 'Subprograme', 'Recursivitate', 'Diverse', 'Ce va afișa pe ecran apelul f(12345) în urma executării codului de mai jos?', NULL, 'void f(int n) {
    if (n!=0) {
        if (n%2==0) cout<<n%10;
        f(n/10);
        if (n%2!=0) cout<<n%10;
    }
    else cout<<"-";
}', '["42-135","42-531","531-42","24-531"]'::jsonb, 0, 'La apelul recursiv (pe coborâre), înainte de auto-apel se afișează cifrele pare (4, apoi 2). Când n ajunge la 0, se afișează caracterul "-". La revenirea din recursivitate (pe urcare), se afișează cifrele impare (1, apoi 3, apoi 5). Astfel, rezultatul concatenat este 42-135.'),\n(36, 'hard', 'code', 'Subprograme', 'Recursivitate', 'Diverse', 'Completează funcția recursivă pentru a calcula factorialul unui număr n. Dacă n este 0, rezultatul este 1.', NULL, 'int fact(int n) {\n    if (n == 0) return 1;\n    return n * ________;\n}', '["fact(n)","fact(n-1)","n-1","fact(n+1)"]'::jsonb, 1, 'Pentru a calcula factorialul, înmulțim n cu factorialul numerelor mai mici decât el, deci apelăm funcția cu n-1: fact(n-1).'),\n(37, 'medium', 'choice', 'Backtracking', 'Teorie si aplicare practica', 'Diverse', 'Generând șirurile de exact 2 caractere distincte din mulțimea {A, B, C, D}, ordonate lexicografic (alfabetic), obținem succesiv: AB, AC, AD, BC, ... Ce se va afișa imediat după BD?', NULL, NULL, '["CA","CB","CD","Nu se va afișa nimic"]'::jsonb, 2, 'Dupa epuizarea sirurilor care incep cu B (BC, BD), algoritmul trece la litera C. Singura varianta valida este CD.'),\n(38, 'easy', 'choice', 'Backtracking', 'Teorie si aplicare practica', 'Diverse', 'Dacă vrem să generăm toate Permutările mulțimii {1, 2, 3}, câte soluții în total ne va oferi algoritmul de Backtracking?', NULL, NULL, '["3 solutii","6 solutii (3!)","9 solutii","1 solutie"]'::jsonb, 1, 'Permutările de n elemente înseamnă toate așezările posibile. Numărul lor este n factorial (3!). 1*2*3 = 6 soluții.'),\n(39, 'hard', 'choice', 'Backtracking', 'Teorie si aplicare practica', 'Diverse', 'Utilizând metoda backtracking, se generează toate numerele de mașină formate din:\n- indicativ județ {B, BR, HD, MM, SV, TL};\n- număr din 2 cifre distincte din {2,4,6,8} în ordine strict crescătoare;\n- 3 litere distincte din {A,B,C} cu mijlocul A.\n\nPrimele 7 generate sunt B-24-BAC, B-24-CAB, B-26-BAC, B-26-CAB, B-28-BAC, B-28-CAB, B-46-BAC. Indicați soluțiile generate imediat înainte, respectiv imediat după SV-68-CAB.', NULL, NULL, '["MM-68-CAB, SV-86-BAC","SV-46-CAB, TL-24-BAC","SV-48-BAC, SV-68-BAC","SV-68-BAC, TL-24-BAC"]'::jsonb, 3, 'Numerele se generează lexicografic. Înainte de SV-68-CAB este SV-68-BAC (schimbăm literele). Fiind ultima soluție pentru SV, următoarea trece la județul următor (TL-24-BAC).'),\n(40, 'medium', 'choice', 'Backtracking', 'Teorie si aplicare practica', 'Diverse', 'Utilizând metoda backtracking, s-au generat toate codurile posibile pentru deblocarea unor telefoane, coduri de câte 6 cifre distincte, din mulțimea cifrelor, ordonată crescător. Fiecare cod are primele trei cifre impare și ultimele trei cifre pare. Primele patru coduri sunt 135024, 135026, 135028, 135042. Indicați penultimul cod generat.', NULL, NULL, '["957862","957846","975862","975846"]'::jsonb, 2, 'Cel mai mare prefix de cifre impare este 975. Cele mai mari sufixe de cifre pare sunt 862 (penultimul) și 864 (ultimul). Deci penultimul cod este 975862.'),\n(41, 'easy', 'choice', 'Grafuri si Arbori', 'Terminologie grafuri', 'Diverse', 'Din ce sunt formate grafurile neorientate?', NULL, NULL, '["Doar din numere si plusuri","Din noduri (puncte) și muchii (linii între puncte)","Din cuvinte asezate in tabel","Din poze"]'::jsonb, 1, 'Un graf matematic este format pur și simplu dintr-o mulțime de puncte (numite Noduri sau Vârfuri) și linii care le unesc, numite Muchii (grafuri neorientate) sau Arce (grafuri orientate).'),\n(42, 'easy', 'choice', 'Grafuri si Arbori', 'Terminologie grafuri', 'Diverse', 'Ce înseamnă că două noduri dintr-un graf sunt "adiacente"?', NULL, NULL, '["Sunt vecine, adica au o linie (muchie) directa intre ele","Sunt cele mai indepartate noduri","Au acelasi numar de muchii","Nu au nicio legatura intre ele"]'::jsonb, 0, 'Adiacent înseamnă practic "vecin". Dacă există o linie directă de la un punct la altul, ele sunt adiacente.'),\n(43, 'easy', 'choice', 'Grafuri si Arbori', 'Terminologie grafuri', 'Diverse', 'Ce reprezintă "gradul" unui nod într-un graf neorientat?', NULL, NULL, '["Numarul de arce care intră în el.","Numarul pe care il poarta (eticheta)","Numarul de linii (muchii) care se prind de el","Numarul de arce care ies din el."]'::jsonb, 2, 'Gradul înseamnă câți "prieteni" direcți are acel nod. Numărăm pur și simplu câte muchii pornesc/ajung fix în el.'),\n(44, 'easy', 'choice', 'Grafuri si Arbori', 'Terminologie grafuri', 'Diverse', 'Ce este un Graf Complet?', NULL, NULL, '["Un graf in care toate muchiile au lungime 10","Un graf desenat perfect patrat","Un graf in care oricare doua noduri au linie intre ele","Un graf din care putem ajunge dintr-un nod în oricare alt nod prin noduri intermediare."]'::jsonb, 2, 'Complet înseamnă că toată lumea e conectată cu toată lumea. Orice pereche de 2 noduri are obligatoriu muchie între ele.'),\n(45, 'easy', 'choice', 'Grafuri si Arbori', 'Grafuri orientate', 'Diverse', 'Într-un graf orientat, liniile au un sens clar (sunt niște săgeți care pleacă din x spre y). Cum se numesc aceste linii?', NULL, NULL, '["Muchii","Arce","Linii de forta","Pointeri"]'::jsonb, 1, 'La grafurile neorientate folosim termenul "Muchii". La grafurile orientate (cu săgeți, direcție precisă), le numim "Arce".'),\n(46, 'easy', 'choice', 'Grafuri si Arbori', 'Grafuri orientate', 'Diverse', 'Ce reprezintă gradul intern (d-) al unui nod într-un graf orientat?', NULL, NULL, '["Cate sageti ies din acel nod spre altele","Suma tuturor numerelor","Cate sageti intra in acel nod","Gradul inmultit cu 2"]'::jsonb, 2, 'Gradul intern înseamnă numărul de arce (săgeți) care INTRĂ (sosesc) în acel nod dinspre altele.'),\n(47, 'easy', 'choice', 'Grafuri si Arbori', 'Grafuri neorientate', 'Diverse', 'Care este o proprietate de bază a matricei de adiacență pentru un graf neorientat?', NULL, NULL, '["Este plina doar de numarul 2","Este simetrică față de diagonala principală","Are doar cifre pare pe colturi","Toate valorile adunate dau un numar prim"]'::jsonb, 1, 'Într-un graf neorientat, dacă nodul 1 are drum la 2, și 2 are drum înapoi la 1. Asta face ca matricea să arate ca o oglindă (simetrică) pe diagonala principală.'),\n(48, 'easy', 'choice', 'Grafuri si Arbori', 'Grafuri neorientate', 'Diverse', 'Suma gradelor tuturor nodurilor dintr-un graf neorientat cu "m" muchii este egală cu:', NULL, NULL, '["m!","m / 2","m * m","2 * m "]'::jsonb, 3, 'Fiecare muchie unește exact 2 noduri. Deci ea "adaugă" grad și la un capăt, și la celălalt. Prin urmare, o muchie crește suma totală a gradelor cu 2.'),\n(49, 'easy', 'choice', 'Grafuri si Arbori', 'Arbori', 'Diverse', 'Ce este mai exact un "Arbore" în teoria grafurilor?', NULL, NULL, '["Un graf cu o singura muchie","Un graf orientat care are cicluri","Un graf conex care nu are cicluri","Un graf care are n-1 muchii"]'::jsonb, 2, 'Arborele e pur și simplu un graf neorientat, legat complet (conex), dar din care, dacă pleci de la un nod pe muchii, nu poți face un "cerc" ca să te întorci de unde ai plecat (fără cicluri).'),\n(50, 'easy', 'choice', 'Grafuri si Arbori', 'Arbori', 'Diverse', 'Câte muchii are garantat un Arbore format din "n" noduri?', NULL, NULL, '["n","n + 1","n - 1","n * 2"]'::jsonb, 2, 'Regula de bază spune că orice arbore are cu exact o muchie mai puțin decât numărul lui de noduri. Dacă are 10 puncte, are 9 linii de legătură (n - 1).'),\n(52, 'medium', 'choice', 'Fundamente', 'Operatori si expresii', 'Diverse', 'Care dintre următoarele expresii C++ verifică dacă o variabilă întreagă x aparține intervalului închis [10, 50] și este totodată un număr divizibil cu 3 sau cu 5?', NULL, NULL, '["(x >= 10 && x <= 50) && (x % 3 == 0 || x % 5 == 0)","(x > 10 || x < 50) && (x % 3 == 0 && x % 5 == 0)","x >= 10 || x <= 50 || x % 15 == 0","(x >= 10 && x <= 50) || (x % 3 == 0 || x % 5 == 0)"]'::jsonb, 0, 'Prima parte (x >= 10 && x <= 50) garantează că x se află în intervalul închis [10, 50]. A doua parte (x % 3 == 0 || x % 5 == 0) verifică divizibilitatea cu 3 sau 5, legate prin operatorul logic AND (&&).'),\n(53, 'medium', 'code', 'Fundamente', 'Structuri de control', 'Diverse', 'Ce se va afișa pe ecran în urma executării următorului algoritm?', NULL, 'int contor = 0;
for (int i = 1; i <= 4; i++) {
